import re
for c in b.claims:
    for key in ['statement','status_on_pages','computation','fate','fate_date','present_status']:
        value=c[key]
        for old,new in spacing.items():value=value.replace(old,new)
        value=re.sub(r'\b(Theorem|Theorems|Proposition|Example|Figure|Definition|Corollary|Lemma|printed|circulation|publication|preprint|spring|copyright|before|account|journal|audit)(?=\d)',r'\1 ',value)
        value=re.sub(r'\b(McReynolds|Kent|Collas|Oesterlé|Zvonkin|Bétréma–Zvonkin|Lando–Zvonkin|Jones|Guillot|Cañas et al\.|Adrianov et al\.|Constantin–Kolev|Morvan|Wood|Ellenberg)(?=\d)',r'\1 ',value)
        c[key]=value
b.BASE.joinpath('claims.json').write_text(b.json.dumps(b.claims,ensure_ascii=False,indent=2)+'\n')
b.BASE.joinpath('claim_search_groups.json').write_text(b.json.dumps(b.search_groups,indent=2)+'\n')
print(len(b.claims),'claims saved')
